contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        // perform deposit if requested (top-level state-changing call)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        // observe C's balance immediately before withdrawAll
        uint balanceBefore = address(c).balance;
        // call withdrawAll and record whether it reverted (top-level try)
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        // observe C's balance after withdrawAll
        uint balanceAfter = address(c).balance;
        // General rule: withdrawAll does not increase C's observable Ether balance
        assert(balanceAfter <= balanceBefore);
    }
    receive() external payable {}
}

